CREATE POLICY planora_maintenance ON "Organization" TO CURRENT_USER USING (true) WITH CHECK (true);
CREATE POLICY planora_tenant ON "Organization" USING ("id" = planora_session_tenant()) WITH CHECK (("id" = planora_session_tenant()));

